}

fn isBootstrapIdentifierByte(byte: u8) bool {
    return std.ascii.isAlphanumeric(byte) or byte == '_' or byte == '$';
}

fn previousBootstrapNonSpaceByte(source: []const u8, idx: usize) ?u8 {
    var cursor = idx;
    while (cursor > 0) {
        cursor -= 1;
        if (!std.ascii.isWhitespace(source[cursor])) return source[cursor];
    }
    return null;
}

fn nextBootstrapNonSpaceByte(source: []const u8, idx: usize) ?u8 {
    var cursor = idx + 1;
    while (cursor < source.len) : (cursor += 1) {
        if (!std.ascii.isWhitespace(source[cursor])) return source[cursor];
    }
    return null;
}

fn isBootstrapExpressionEndByte(byte: u8) bool {
    return isBootstrapIdentifierByte(byte) or byte == ')' or byte == ']';
}

fn isBootstrapNonNullFollower(byte: u8) bool {
    return switch (byte) {
        '.', '[', '(', ')', ',', ';', ':', '?', '}', '+', '-', '*', '/', '%', '|', '&', '^', '<', '>' => true,
        else => false,
    };
}

fn isBootstrapTypeScriptNonNullAssertion(source: []const u8, idx: usize) bool {
    if (source[idx] != '!') return false;
    if (idx + 1 < source.len and source[idx + 1] == '=') return false;

    const previous = previousBootstrapNonSpaceByte(source, idx) orelse return false;
    if (!isBootstrapExpressionEndByte(previous)) return false;

    const next = nextBootstrapNonSpaceByte(source, idx) orelse return true;
    return isBootstrapNonNullFollower(next);
}

fn rewriteBootstrapUsingDeclarationLines(allocator: std.mem.Allocator, source: []const u8) !?[]u8 {
    if (std.mem.indexOf(u8, source, "describe(\"minimum-release-age\"") == null) return null;
    if (std.mem.indexOf(u8, source, "using ") == null) return null;

    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);

    var changed = false;
    var line_start: usize = 0;
    while (line_start < source.len) {
        const line_end = std.mem.indexOfScalarPos(u8, source, line_start, '\n') orelse source.len;
        const line = source[line_start..line_end];
        var cursor: usize = 0;
        while (cursor < line.len and (line[cursor] == ' ' or line[cursor] == '\t')) : (cursor += 1) {}

        if (std.mem.startsWith(u8, line[cursor..], "await using ")) {
            try out.appendSlice(allocator, line[0..cursor]);
            try out.appendSlice(allocator, "const ");
            try out.appendSlice(allocator, line[cursor + "await using ".len ..]);
            changed = true;
        } else if (std.mem.startsWith(u8, line[cursor..], "using ")) {
            try out.appendSlice(allocator, line[0..cursor]);
            try out.appendSlice(allocator, "const ");
            try out.appendSlice(allocator, line[cursor + "using ".len ..]);
            changed = true;
        } else {
            try out.appendSlice(allocator, line);
        }

        if (line_end < source.len) {
            try out.append(allocator, '\n');
            line_start = line_end + 1;
        } else {
            line_start = line_end;
        }
    }

    if (!changed) {
        out.deinit(allocator);
        return null;
    }
    return try out.toOwnedSlice(allocator);
}

fn isBootstrapLineStatementStart(source: []const u8, idx: usize) bool {
    var cursor = idx;
    while (cursor > 0 and source[cursor - 1] != '\n' and source[cursor - 1] != '\r') : (cursor -= 1) {}
    while (cursor < idx) : (cursor += 1) {
        if (source[cursor] != ' ' and source[cursor] != '\t') return false;
    }
    return true;
}

fn appendBootstrapUsingDeclarationRewrite(out: *std.ArrayList(u8), allocator: std.mem.Allocator, source: []const u8, idx: usize) !?usize {
    if (!isBootstrapLineStatementStart(source, idx)) return null;
    if (std.mem.startsWith(u8, source[idx..], "await using ")) {
        try out.appendSlice(allocator, "const ");
        return idx + "await using ".len;
    }
    if (std.mem.startsWith(u8, source[idx..], "using ")) {
        try out.appendSlice(allocator, "const ");
        return idx + "using ".len;
    }
    return null;
}

fn skipBootstrapTypeAlias(source: []const u8, idx: usize) ?usize {
    if (!isBootstrapLineStatementStart(source, idx) or !std.mem.startsWith(u8, source[idx..], "type ")) return null;

    const Mode = enum { code, single_quote, double_quote, template, line_comment, block_comment };
    var mode: Mode = .code;
    var braces: usize = 0;
    var brackets: usize = 0;
    var parens: usize = 0;
    var saw_equals = false;
    var cursor = idx + "type ".len;

    while (cursor < source.len) : (cursor += 1) {
        const byte = source[cursor];
        switch (mode) {
            .code => {
                if (byte == '\'') {
                    mode = .single_quote;
                } else if (byte == '"') {
                    mode = .double_quote;
                } else if (byte == '`') {
                    mode = .template;
                } else if (byte == '/' and cursor + 1 < source.len and source[cursor + 1] == '/') {
                    mode = .line_comment;
                    cursor += 1;
                } else if (byte == '/' and cursor + 1 < source.len and source[cursor + 1] == '*') {
                    mode = .block_comment;
                    cursor += 1;
                } else switch (byte) {
                    '=' => saw_equals = true,
                    '{' => braces += 1,
                    '}' => if (braces > 0) {
                        braces -= 1;
                    },
                    '[' => brackets += 1,
                    ']' => if (brackets > 0) {
                        brackets -= 1;
                    },
                    '(' => parens += 1,
                    ')' => if (parens > 0) {
                        parens -= 1;
                    },
                    ';' => if (saw_equals and braces == 0 and brackets == 0 and parens == 0) {
                        return cursor + 1;
                    },
                    else => {},
                }
            },
            .single_quote, .double_quote, .template => {
                const terminator: u8 = switch (mode) {
                    .single_quote => '\'',
                    .double_quote => '"',
                    .template => '`',
                    else => unreachable,
                };
                if (byte == '\\' and cursor + 1 < source.len) {
                    cursor += 1;
                } else if (byte == terminator) {
                    mode = .code;
                }
            },
            .line_comment => if (byte == '\n') {
                mode = .code;
            },
            .block_comment => if (byte == '*' and cursor + 1 < source.len and source[cursor + 1] == '/') {
                mode = .code;
                cursor += 1;
            },
        }
    }
    return null;
}

fn skipBootstrapDeclareModule(source: []const u8, idx: usize) ?usize {
    if (!isBootstrapLineStatementStart(source, idx) or !std.mem.startsWith(u8, source[idx..], "declare module ")) return null;

    const Mode = enum { code, single_quote, double_quote, template, line_comment, block_comment };
    var mode: Mode = .code;
    var depth: usize = 0;
    var cursor = idx + "declare module ".len;
    var saw_body = false;
    while (cursor < source.len) : (cursor += 1) {
        const byte = source[cursor];
        switch (mode) {
            .code => {
                if (byte == '\'') {
                    mode = .single_quote;
                } else if (byte == '"') {
                    mode = .double_quote;
                } else if (byte == '`') {
                    mode = .template;
                } else if (byte == '/' and cursor + 1 < source.len and source[cursor + 1] == '/') {
                    mode = .line_comment;
                    cursor += 1;
                } else if (byte == '/' and cursor + 1 < source.len and source[cursor + 1] == '*') {
                    mode = .block_comment;
                    cursor += 1;
                } else if (byte == '{') {
                    saw_body = true;
                    depth += 1;
                } else if (byte == '}' and saw_body) {
                    if (depth == 0) return null;
                    depth -= 1;
                    if (depth == 0) {
                        cursor += 1;
                        if (cursor < source.len and source[cursor] == ';') cursor += 1;
                        while (cursor < source.len and (source[cursor] == '\n' or source[cursor] == '\r')) cursor += 1;
                        return cursor;
                    }
                }
            },
            .single_quote, .double_quote, .template => {
                const terminator: u8 = switch (mode) {
                    .single_quote => '\'',
                    .double_quote => '"',
                    .template => '`',
                    else => unreachable,
                };
                if (byte == '\\' and cursor + 1 < source.len) {
                    cursor += 1;
                } else if (byte == terminator) {
                    mode = .code;
                }
            },
            .line_comment => if (byte == '\n') {
                mode = .code;
            },
            .block_comment => if (byte == '*' and cursor + 1 < source.len and source[cursor + 1] == '/') {
                mode = .code;
                cursor += 1;
            },
        }
    }
    return null;
}

fn skipBootstrapFunctionReturnType(source: []const u8, idx: usize) ?usize {
    if (idx >= source.len or source[idx] != ':') return null;
    var previous = idx;
    while (previous > 0 and isJsWhitespace(source[previous - 1])) previous -= 1;
    if (previous == 0 or source[previous - 1] != ')') return null;
    const context_start = idx -| 512;
    if (std.mem.lastIndexOf(u8, source[context_start..idx], "function ") == null) return null;

    const Mode = enum { code, single_quote, double_quote, line_comment, block_comment };
    var mode: Mode = .code;
    var angles: usize = 0;
    var brackets: usize = 0;
    var parens: usize = 0;
    var braces: usize = 0;
    var first_type_byte: ?usize = null;
    var cursor = idx + 1;
    while (cursor < source.len) : (cursor += 1) {
        const byte = source[cursor];
        switch (mode) {
            .code => {
                if (first_type_byte == null and !isJsWhitespace(byte)) first_type_byte = cursor;
                if (byte == '\'') {
                    mode = .single_quote;
                } else if (byte == '"') {
                    mode = .double_quote;
                } else if (byte == '/' and cursor + 1 < source.len and source[cursor + 1] == '/') {
                    mode = .line_comment;
                    cursor += 1;
                } else if (byte == '/' and cursor + 1 < source.len and source[cursor + 1] == '*') {
                    mode = .block_comment;
                    cursor += 1;
                } else switch (byte) {
                    '<' => angles += 1,
                    '>' => if (angles > 0) {
                        angles -= 1;
                    } else if (cursor + 1 < source.len and source[cursor + 1] == '=' and brackets == 0 and parens == 0 and braces == 0) {
                        return cursor;
                    },
                    '[' => brackets += 1,
                    ']' => if (brackets > 0) {
                        brackets -= 1;
                    },
                    '(' => parens += 1,
                    ')' => if (parens > 0) {
                        parens -= 1;
                    },
                    '{' => if (angles == 0 and brackets == 0 and parens == 0 and braces == 0 and first_type_byte != cursor) {
                        return cursor;
                    } else {
                        braces += 1;
                    },
                    '}' => if (braces > 0) {
                        braces -= 1;
                    },
                    else => {},
                }
            },
            .single_quote, .double_quote => {
                const terminator: u8 = if (mode == .single_quote) '\'' else '"';
                if (byte == '\\' and cursor + 1 < source.len) {
                    cursor += 1;
                } else if (byte == terminator) {
                    mode = .code;
                }
            },
            .line_comment => if (byte == '\n') {
                mode = .code;
            },
            .block_comment => if (byte == '*' and cursor + 1 < source.len and source[cursor + 1] == '/') {
                mode = .code;
                cursor += 1;
            },
        }
    }
    return null;
}

fn bootstrapReplacementWouldEraseTernaryFalseBranch(source: []const u8, idx: usize, needle: []const u8) bool {
    if (!std.mem.startsWith(u8, needle, ": ")) return false;
    const can_erase_expression =
        std.mem.endsWith(u8, needle, ";") or
        std.mem.endsWith(u8, needle, ")") or
        std.mem.endsWith(u8, needle, "=>");
    if (!can_erase_expression) return false;
