fn sourceNeedsBootstrapTypeScriptRewrite(source: []const u8, relative_path: []const u8) bool {
    if (std.mem.endsWith(u8, relative_path, ".ts") or
        std.mem.endsWith(u8, relative_path, ".tsx") or
        std.mem.endsWith(u8, relative_path, ".mts") or
        std.mem.endsWith(u8, relative_path, ".cts"))
    {
        return true;
    }

    const markers = [_][]const u8{
        "await import(",
        "import(",
        "interface ",
        "type ",
        " as ",
        "using ",
        "!:",
        "!.",
        "![",
        "!;",
        "new Promise<",
        "Promise.withResolvers<",
        "constructor(public",
        "private ",
        "override ",
        "readonly ",
        ": any",
        ": string",
        ": number",
        ": Buffer",
        ": URL",
        ": Event",
        ": Error",
        ": Promise",
        ": Record",
        ": Array",
        ": Fetch",
        ": Test",
        "export {};",
    };
    for (markers) |marker| {
        if (std.mem.indexOf(u8, source, marker) != null) return true;
    }
    return false;
}

fn finishModuleRewrite(allocator: std.mem.Allocator, source: []const u8, relative_path: []const u8) ![]u8 {
    const with_buffered_response_initializers = try std.mem.replaceOwned(
        u8,
        allocator,
        source,
        "await response.clone().blob()",
        "__home_response_blob_sync(response.clone())",
    );
    defer allocator.free(with_buffered_response_initializers);

    const with_module_imports = try rewriteBootstrapModuleImports(allocator, with_buffered_response_initializers);
    defer allocator.free(with_module_imports);

    const with_import_meta = try rewriteImportMeta(allocator, with_module_imports);
    defer allocator.free(with_import_meta);

    if (!sourceNeedsBootstrapTypeScriptRewrite(with_import_meta, relative_path)) {
        return allocator.dupe(u8, with_import_meta);
    }

    const with_bootstrap_ts = try rewriteBootstrapTypeScript(allocator, with_import_meta);
    defer allocator.free(with_bootstrap_ts);
    return stripTypeScriptNonNullAssertions(allocator, with_bootstrap_ts);
}

