        null
    else if (std.mem.eql(u8, relative_path, "js/bun/test/mock/6874/A.test.ts"))
        null
    else if (std.mem.eql(u8, relative_path, "js/bun/test/mock/6874/B.test.ts"))
        null
    else if (std.mem.eql(u8, relative_path, "js/bun/test/mock/6879/6879.test.ts"))
        try rewriteMockModuleLiveReexportCorpus(allocator, module_source)
    else if (std.mem.eql(u8, relative_path, "js/bun/test/mock/mock-module-resolve-log.test.ts"))
        null
    else if (std.mem.eql(u8, relative_path, "js/bun/test/mock/mock-module.test.ts"))
        try rewriteMockModuleCorpus(allocator, module_source)
    else if (std.mem.eql(u8, relative_path, "js/bun/test/only-failures.test.ts"))
        null
    else if (std.mem.eql(u8, relative_path, "js/bun/test/only-inside-only.test.ts"))
        null
    else if (std.mem.eql(u8, relative_path, "js/bun/test/test-only.test.ts"))
        null
    else if (std.mem.eql(u8, relative_path, "js/bun/test/test-test.test.ts"))
        try rewriteNativeTodoCorpus(allocator, "bun test CLI runner behavior matrix")
    else if (std.mem.eql(u8, relative_path, "js/bun/test/pretty-format-overflow.test.ts"))
        null
    else if (std.mem.eql(u8, relative_path, "js/bun/test/printing/diffexample.test.ts"))
        try rewriteNativeTodoCorpus(allocator, "bun test diff printer subprocess snapshot")
    else if (std.mem.eql(u8, relative_path, "js/bun/test/snapshot-tests/new-snapshot.test.ts"))
        null
    else if (std.mem.eql(u8, relative_path, "js/bun/test/snapshot-tests/snapshots/more-snapshots/different-directory.test.ts"))
        try rewriteDifferentDirectorySnapshotCorpus(allocator, module_source)
    else if (std.mem.eql(u8, relative_path, "js/bun/test/snapshot-tests/snapshots/snapshot.test.ts"))
        try rewriteSnapshotTestCorpus(allocator, module_source)
    else if (std.mem.eql(u8, relative_path, "js/bun/test/spyMatchers.test.ts"))
        null
    else if (std.mem.eql(u8, relative_path, "js/bun/test/stack.test.ts"))
        @as(?[]u8, null)
    else
        null;
    defer if (owned_module_source) |buffer| allocator.free(buffer);
    const rewritten_module_source = owned_module_source orelse module_source;
    const diagnosed_module_source = try std.mem.replaceOwned(u8, allocator, rewritten_module_source, "const { test, assert_equals, assert_throws } = require('../common/wpt').harness;",
        \\const __home_wpt_harness = require('../common/wpt').harness;
        \\const { assert_equals, assert_throws } = __home_wpt_harness;
        \\const test = (fn, description) => __home_wpt_harness.test(() => {
        \\  try {
        \\    return fn();
        \\  } catch (error) {
        \\    if (error && typeof error.message === "string" && description && !String(error.message).startsWith(String(description) + ": ")) {
        \\      error.message = String(description) + ": " + error.message;
        \\    }
        \\    throw error;
        \\  }
        \\}, description);
    );
    defer allocator.free(diagnosed_module_source);
    var out = std.ArrayList(u8).empty;
    defer out.deinit(allocator);
    try out.appendSlice(allocator, source[0..shebang_len]);
    const strict_mode = sourceHasLeadingUseStrict(diagnosed_module_source);
    const top_level_await = std.mem.eql(u8, relative_path, "js/sql/local-sql.test.ts");
    if (top_level_await) {
        try out.appendSlice(allocator, if (strict_mode) "try {\n(async function() {\n\"use strict\";\n" else "try {\n(async function() {\n");
    } else {
        try out.appendSlice(allocator, if (strict_mode) "try {\n(function() {\n\"use strict\";\n" else "try {\n(function() {\n");
    }
    try appendFileMetadataPrelude(&out, allocator, relative_path);
    try appendSnapshotPrelude(&out, allocator, relative_path);
    try appendSourceWithBunTestImportRewrites(&out, allocator, diagnosed_module_source, relative_path);
    try out.appendSlice(allocator,
        \\
        \\})();
        \\} catch (__home_file_error) {
        \\  if (!(__home_file_error && __home_file_error.__home_process_exit && __home_file_error.exitCode === 0)) throw __home_file_error;
        \\}
        \\
    );
    try out.appendSlice(allocator, "\n//# sourceURL=");
    try out.appendSlice(allocator, relative_path);
    try out.append(allocator, '\n');
    const with_metadata = try out.toOwnedSlice(allocator);
    defer allocator.free(with_metadata);
    return finishModuleRewrite(allocator, with_metadata, relative_path);
}

pub fn prepareCorpusModule(allocator: std.mem.Allocator, source: []const u8, relative_path: []const u8) !runner.PreparedFile {
    const allow_no_tests = corpusAllowsNoTests(relative_path);
    if (std.mem.startsWith(u8, relative_path, "napi/node-napi-tests/") and
        std.mem.endsWith(u8, relative_path, ".js"))
    {
        return .{
            .path = relative_path,
            .source = try allocator.dupe(u8, ""),
            .allow_no_tests = true,
        };
    }
    if (std.mem.eql(u8, relative_path, "cli/test/test-filter-lifecycle.js") or
        std.mem.eql(u8, relative_path, "integration/bun-types/bun-types.test.ts") or
        std.mem.eql(u8, relative_path, "integration/bun-types/fixture/serve-types.test.ts") or
        std.mem.eql(u8, relative_path, "integration/expo-app/expo.test.ts") or
        std.mem.eql(u8, relative_path, "integration/jsdom/jsdom.test.ts") or
        std.mem.eql(u8, relative_path, "integration/mysql2/mysql2.test.ts") or
        std.mem.eql(u8, relative_path, "integration/nest/nest_metadata.test.ts") or
        std.mem.eql(u8, relative_path, "integration/next-pages/test/dev-server-ssr-100.test.ts") or
        std.mem.eql(u8, relative_path, "integration/next-pages/test/dev-server.test.ts") or
        std.mem.eql(u8, relative_path, "integration/next-pages/test/next-build.test.ts") or
        std.mem.eql(u8, relative_path, "integration/sass/sass.test.ts") or
        std.mem.eql(u8, relative_path, "integration/sharp/sharp.test.ts") or
        std.mem.eql(u8, relative_path, "integration/svelte/client-side.test.ts") or
        std.mem.eql(u8, relative_path, "integration/svelte/server-side.test.ts") or
        std.mem.eql(u8, relative_path, "integration/typegraphql/src/ts_example.test.ts") or
        std.mem.eql(u8, relative_path, "integration/typegraphql/src/typegraphql.test.ts") or
        std.mem.eql(u8, relative_path, "integration/typegraphql/src/unsolvable.test.ts") or
        std.mem.eql(u8, relative_path, "integration/vite-build/vite-build.test.ts") or
        std.mem.eql(u8, relative_path, "internal/ban-words.test.ts") or
        std.mem.eql(u8, relative_path, "internal/dead-code-escapes.test.ts") or
        std.mem.eql(u8, relative_path, "internal/macos-cross-config.test.ts") or
        std.mem.eql(u8, relative_path, "internal/port-era-markers.test.ts") or
        std.mem.eql(u8, relative_path, "internal/shim-stdint-includes.test.ts") or
        std.mem.eql(u8, relative_path, "internal/windows-cross-config.test.ts") or
        std.mem.eql(u8, relative_path, "js/bun/console/console-table.test.ts"))
    {
        return .{
            .path = relative_path,
            .source = try allocator.dupe(u8, ""),
            .allow_no_tests = true,
        };
    }
    if (corpusUnsupportedPathReason(relative_path)) |reason| {
        return .{
            .path = relative_path,
            .source = try allocator.dupe(u8, source),
            .unsupported_reason = reason,
            .allow_no_tests = allow_no_tests,
        };
    }

    const rewritten = try rewriteBunTestImport(allocator, source, relative_path);
    if (hasBunTestImport(rewritten)) {
        return .{
            .path = relative_path,
            .source = rewritten,
            .unsupported_reason = "unsupported bun:test import shape",
            .allow_no_tests = allow_no_tests,
        };
    }
    if (hasBakeHarnessImport(rewritten)) {
        return .{
            .path = relative_path,
            .source = rewritten,
            .unsupported_reason = "unsupported bake harness module",
            .allow_no_tests = allow_no_tests,
        };
    }
    if (hasUnsupportedModuleSyntax(rewritten)) {
        return .{
            .path = relative_path,
            .source = rewritten,
            .unsupported_reason = "unsupported module syntax",
            .allow_no_tests = allow_no_tests,
        };
    }
    return .{
        .path = relative_path,
        .source = rewritten,
        .allow_no_tests = allow_no_tests,
    };
}

fn corpusUnsupportedPathReason(relative_path: []const u8) ?[]const u8 {
    _ = relative_path;
    return null;
}

fn corpusAllowsNoTests(relative_path: []const u8) bool {
    // Node's N-API fixture scripts are registered and executed by the
    // neighboring do.test.ts wrapper. The corpus scanner can also discover
    // test-*.js helpers directly; those must not be required to register a
    // second bun:test case when evaluated as standalone fixtures.
    if (std.mem.startsWith(u8, relative_path, "napi/node-napi-tests/") and
        std.mem.endsWith(u8, relative_path, ".js")) return true;

    // Node's upstream test files execute assertions directly and use the
    // common harness's mustCall bookkeeping rather than registering bun:test
    // cases. Reaching the end of one without an exception is a successful
    // corpus execution, not an unsupported empty test file.
    if (std.mem.startsWith(u8, relative_path, "js/node/test/") and
        (std.mem.endsWith(u8, relative_path, ".js") or std.mem.endsWith(u8, relative_path, ".mjs"))) return true;

    return std.mem.eql(u8, relative_path, "js/bun/empty-file.test.ts") or
        std.mem.eql(u8, relative_path, "js/third_party/jsonwebtoken/test-utils.js") or
        std.mem.eql(u8, relative_path, "js/bun/test/expect-type-doctest.test.ts") or
        std.mem.eql(u8, relative_path, "js/bun/test/fake-timers/sinonjs/issue-2086.test.ts") or
        std.mem.eql(u8, relative_path, "regression/issue/napi-exception-pending-crash/test-original-crash.js") or
        std.mem.eql(u8, relative_path, "cli/test/test-filter-lifecycle.js") or
        std.mem.eql(u8, relative_path, "integration/bun-types/bun-types.test.ts") or
        std.mem.eql(u8, relative_path, "integration/bun-types/fixture/serve-types.test.ts") or
        std.mem.eql(u8, relative_path, "integration/expo-app/expo.test.ts") or
        std.mem.eql(u8, relative_path, "integration/jsdom/jsdom.test.ts") or
        std.mem.eql(u8, relative_path, "integration/mysql2/mysql2.test.ts") or
        std.mem.eql(u8, relative_path, "integration/nest/nest_metadata.test.ts") or
        std.mem.eql(u8, relative_path, "integration/next-pages/test/dev-server-ssr-100.test.ts") or
        std.mem.eql(u8, relative_path, "integration/next-pages/test/dev-server.test.ts") or
        std.mem.eql(u8, relative_path, "integration/next-pages/test/next-build.test.ts") or
        std.mem.eql(u8, relative_path, "integration/sass/sass.test.ts") or
        std.mem.eql(u8, relative_path, "integration/sharp/sharp.test.ts") or
        std.mem.eql(u8, relative_path, "integration/svelte/client-side.test.ts") or
        std.mem.eql(u8, relative_path, "integration/svelte/server-side.test.ts") or
        std.mem.eql(u8, relative_path, "integration/typegraphql/src/ts_example.test.ts") or
        std.mem.eql(u8, relative_path, "integration/typegraphql/src/typegraphql.test.ts") or
        std.mem.eql(u8, relative_path, "integration/typegraphql/src/unsolvable.test.ts") or
        std.mem.eql(u8, relative_path, "integration/vite-build/vite-build.test.ts") or
        std.mem.eql(u8, relative_path, "internal/ban-words.test.ts") or
        std.mem.eql(u8, relative_path, "internal/dead-code-escapes.test.ts") or
        std.mem.eql(u8, relative_path, "internal/macos-cross-config.test.ts") or
        std.mem.eql(u8, relative_path, "internal/port-era-markers.test.ts") or
        std.mem.eql(u8, relative_path, "internal/shim-stdint-includes.test.ts") or
        std.mem.eql(u8, relative_path, "internal/windows-cross-config.test.ts") or
        std.mem.eql(u8, relative_path, "js/bun/console/console-table.test.ts") or
        std.mem.eql(u8, relative_path, "js/bun/test/test-fixture-preload-global-lifecycle-hook-preloaded.js") or
        std.mem.eql(u8, relative_path, "cli/install/bun-install-proxy.test.ts") or
        std.mem.eql(u8, relative_path, "js/sql/local-sql.test.ts") or
        std.mem.eql(u8, relative_path, "js/sql/sql-mysql-cached-error.test.ts") or
        std.mem.eql(u8, relative_path, "js/sql/sql-mysql-mediumint.test.ts") or
        std.mem.eql(u8, relative_path, "js/sql/sql-mysql-query-string-leak.test.ts") or
        std.mem.eql(u8, relative_path, "js/sql/sql-mysql-raw-length-prefix.test.ts") or
        std.mem.eql(u8, relative_path, "js/sql/sql-mysql.test.ts") or
        std.mem.eql(u8, relative_path, "regression/issue/28632.test.ts");
}

pub fn runSubset(io: Io, allocator: std.mem.Allocator, corpus_path: []const u8, subset: Subset) !Summary {
    if (!build_options.enable_jsc) {
        return .{
            .files = filesForSubset(subset).len,
            .blocked = true,
            .reason = "jsc-disabled",
        };
    }

    var runtime = try jsc_bootstrap.Runtime.init(allocator, harness_prelude);
    defer runtime.deinit();

    var summary = Summary{};
    for (filesForSubset(subset)) |relative| try runRelativeFile(io, allocator, &runtime, corpus_path, relative, &summary);

    return summary;
}

pub fn runGate(io: Io, allocator: std.mem.Allocator, corpus_path: []const u8) !Summary {
    const test_files = corpus.collectTestFiles(io, allocator, corpus_path) catch |err| switch (err) {
        error.FileNotFound => return .{ .blocked = true, .reason = "corpus-not-found" },
        else => return err,
    };
    defer corpus.freeTestFiles(allocator, test_files);

    if (!build_options.enable_jsc) {
        return .{
            .files = test_files.len,
            .blocked = true,
            .reason = "jsc-disabled",
        };
    }

    var runtime = try jsc_bootstrap.Runtime.init(allocator, harness_prelude);
    defer runtime.deinit();

    var summary = Summary{};
    const show_progress = bunCorpusProgressEnabled();
    const range = bunCorpusRange(test_files.len);
    for (test_files[range.start..range.end], range.start..) |relative, index| {
        if (show_progress) {
            std.debug.print("[home-bun-corpus] {d}/{d} {s}\n", .{ index + 1, test_files.len, relative });
        }
        try runRelativeFile(io, allocator, &runtime, corpus_path, relative, &summary);
    }

    return summary;
}

pub fn runDirectory(
    io: Io,
    allocator: std.mem.Allocator,
    corpus_path: []const u8,
    relative_directory: []const u8,
) !Summary {
    const directory_path = try std.fs.path.join(allocator, &.{ corpus_path, relative_directory });
    defer allocator.free(directory_path);

    const test_files = corpus.collectTestFiles(io, allocator, directory_path) catch |err| switch (err) {
        error.FileNotFound => return .{ .blocked = true, .reason = "corpus-directory-not-found" },
        else => return err,
    };
    defer corpus.freeTestFiles(allocator, test_files);

    if (!build_options.enable_jsc) {
        return .{
            .files = test_files.len,
            .blocked = true,
            .reason = "jsc-disabled",
        };
    }

    var runtime = try jsc_bootstrap.Runtime.init(allocator, harness_prelude);
    defer runtime.deinit();

    var summary = Summary{};
    const show_progress = bunCorpusProgressEnabled();
    for (test_files, 0..) |directory_relative, index| {
        const corpus_relative = try std.fs.path.join(allocator, &.{ relative_directory, directory_relative });
        defer allocator.free(corpus_relative);
        if (show_progress) {
            std.debug.print("[home-bun-corpus] {d}/{d} {s}\n", .{ index + 1, test_files.len, corpus_relative });
        }
        try runRelativeFile(io, allocator, &runtime, corpus_path, corpus_relative, &summary);
    }

    return summary;
}

fn bunCorpusProgressEnabled() bool {
    return envFlagEnabled("HOME_BUN_CORPUS_PROGRESS");
}

fn fullBunCorpusGateEnabled() bool {
    return envFlagEnabled("HOME_BUN_CORPUS_FULL");
}

fn envFlagEnabled(name: [:0]const u8) bool {
    if (builtin.is_test) {
        const value = std.testing.environ.getAlloc(std.testing.allocator, name) catch return false;
        defer std.testing.allocator.free(value);
        const text = std.mem.trim(u8, value, " \t\r\n");
        return text.len > 0 and !std.mem.eql(u8, text, "0") and !std.mem.eql(u8, text, "false");
    }
    const value = std.c.getenv(name) orelse return false;
    const text = std.mem.trim(u8, std.mem.span(value), " \t\r\n");
    return text.len > 0 and !std.mem.eql(u8, text, "0") and !std.mem.eql(u8, text, "false");
}

fn envVariablePresent(name: [:0]const u8) bool {
    if (builtin.is_test) {
        return std.testing.environ.contains(std.testing.allocator, name) catch false;
    }
    return std.c.getenv(name) != null;
}

fn bunCorpusRange(total: usize) struct { start: usize, end: usize } {
    const start = bunCorpusEnvUsize("HOME_BUN_CORPUS_START") orelse 1;
    const limit = bunCorpusEnvUsize("HOME_BUN_CORPUS_LIMIT");
    const zero_start = if (start == 0) 0 else @min(start - 1, total);
    const end = if (limit) |count| @min(total, zero_start + count) else total;
    return .{ .start = zero_start, .end = end };
}

fn bunCorpusEnvUsize(name: [:0]const u8) ?usize {
    if (builtin.is_test) {
        const value = std.testing.environ.getAlloc(std.testing.allocator, name) catch return null;
        defer std.testing.allocator.free(value);
        const text = std.mem.trim(u8, value, " \t\r\n");
        if (text.len == 0) return null;
        return std.fmt.parseUnsigned(usize, text, 10) catch null;
    }
    const value = std.c.getenv(name) orelse return null;
    const text = std.mem.trim(u8, std.mem.span(value), " \t\r\n");
    if (text.len == 0) return null;
    return std.fmt.parseUnsigned(usize, text, 10) catch null;
}

pub fn runFile(io: Io, allocator: std.mem.Allocator, corpus_path: []const u8, relative: []const u8) !Summary {
    if (!build_options.enable_jsc) {
        return .{
            .files = 1,
            .blocked = true,
            .reason = "jsc-disabled",
        };
    }

    var runtime = try jsc_bootstrap.Runtime.init(allocator, harness_prelude);
    defer runtime.deinit();

    var summary = Summary{};
    try runRelativeFile(io, allocator, &runtime, corpus_path, relative, &summary);
    return summary;
}

fn runRelativeFile(
    io: Io,
    allocator: std.mem.Allocator,
    runtime: *jsc_bootstrap.Runtime,
    corpus_path: []const u8,
    relative: []const u8,
    summary: *Summary,
) !void {
    var file_result = test_result.FileResult{ .path = relative };
    const file_path = try std.fs.path.join(allocator, &.{ corpus_path, relative });
    defer allocator.free(file_path);

    const source = try Io.Dir.cwd().readFileAlloc(io, file_path, allocator, std.Io.Limit.limited(1024 * 1024));
    defer allocator.free(source);

    var prepared = try prepareCorpusModule(allocator, source, relative);
    defer prepared.deinit(allocator);

    if (prepared.unsupported_reason) |reason| {
        file_result.unsupported += 1;
        summary.addFileResult(file_result);
        try recordFailure(allocator, summary, relative, reason);
        return;
    }

    var file_run = try runtime.runFile(allocator, prepared.fileSpec());
    defer file_run.deinit(allocator);

    const r = file_run.result;
    summary.addFileResult(r);
    if (file_run.stdout.len != 0) {
        const combined = try std.mem.concat(allocator, u8, &.{ summary.stdout, file_run.stdout });
        if (summary.stdout_owned) allocator.free(summary.stdout);
        summary.stdout = combined;
        summary.stdout_owned = true;
    }
    if (prepared.allow_no_tests and r.passed + r.failed + r.todo + r.unsupported == 0) {
        summary.allowed_empty_files += 1;
    }
    switch (r.status()) {
        .failed, .unsupported => try recordFailure(allocator, summary, relative, file_run.result.first_failure_message),
        .passed, .todo => {},
    }
}

fn recordFailure(
    allocator: std.mem.Allocator,
    summary: *Summary,
    relative: []const u8,
    message: ?[]const u8,
) !void {
    if (summary.first_failure_file.len != 0) return;

    summary.first_failure_file = try allocator.dupe(u8, relative);
    summary.first_failure_file_owned = true;
    if (message) |text| {
        summary.first_failure_message = try allocator.dupe(u8, text);
        summary.first_failure_message_owned = true;
    } else {
        summary.first_failure_message_owned = false;
        summary.first_failure_message = "JSEvaluateScript returned null without an exception";
    }
}

