test "bootstrap runner mirrors transpiler type coercion corpus" {
    if (!build_options.enable_jsc) return error.SkipZigTest;

    const source =
        \\import { describe, expect, it } from "bun:test";
        \\
        \\describe("Bun.Transpiler", () => {
