        \\    let data = "";
        \\    req.on("data", chunk => { data += chunk; });
        \\    req.on("end", () => { resolve(data); client.close(); });
        \\    req.on("error", reject);
        \\    req.end();
        \\  });
        \\  expect(result).toBe("OK");
        \\  expect(receivedDataFrames.length).toBe(0);
        \\  server.close();
        \\});
        \\
        \\test("end data sends one data frame", async () => {
