test "bootstrap runner covers current S3 file type header validation" {
    if (!build_options.enable_jsc) return error.SkipZigTest;

    const source =
        \\import { expect, test } from "bun:test";
        \\
        \\test("S3 file type option containing control characters is not reflected into upload request headers", async () => {
        \\  const seenRequests = [];
        \\  const endpoint = "http://s3.local";
        \\  globalThis.__home_serve_handles_by_origin[endpoint] = {
        \\    stopped: false,
        \\    fetch(req) {
        \\      seenRequests.push({ headers: req.headers, url: req.url });
        \\      return new Response("", { status: 200 });
        \\    },
        \\  };
        \\
        \\  const client = new Bun.S3Client({
        \\    accessKeyId: "test",
        \\    secretAccessKey: "test",
        \\    region: "eu-west-3",
        \\    bucket: "my_bucket",
        \\    endpoint,
        \\  });
        \\
        \\  expect(() => client.file("report.txt", { type: "text/plain\r\nx-amz-acl: public-read" })).toThrow("type must not contain newline characters (CR/LF)");
        \\
        \\  const file = client.file("report.txt", { type: "text/plain\x0bx-amz-acl: public-read" });
        \\  expect(file.type).not.toContain("\x0b");
        \\  expect(file.type).not.toContain("public-read");
        \\  await file.write("hello");
        \\
        \\  expect(seenRequests.length).toBeGreaterThan(0);
        \\  for (const seen of seenRequests) {
        \\    expect(seen.headers.get("x-amz-acl")).toBeNull();
        \\    expect(seen.headers.get("content-type") ?? "").not.toContain("public-read");
        \\    expect(seen.headers.get("content-type") ?? "").not.toContain("\x0b");
        \\  }
        \\
        \\  const before = seenRequests.length;
        \\  await client.file("plain.txt", { type: "text/plain" }).write("hello");
        \\  const legit = seenRequests.slice(before);
        \\  expect(legit.length).toBeGreaterThan(0);
        \\  expect(legit.some(seen => (seen.headers.get("content-type") ?? "").startsWith("text/plain"))).toBe(true);
        \\  for (const seen of legit) expect(seen.headers.get("x-amz-acl")).toBeNull();
        \\  delete globalThis.__home_serve_handles_by_origin[endpoint];
        \\});
    ;
    var prepared = try prepareCorpusModule(std.testing.allocator, source, "js/bun/s3/s3-fd-validation.test.ts");
    defer prepared.deinit(std.testing.allocator);

    try std.testing.expect(prepared.unsupported_reason == null);
    try std.testing.expect(std.mem.indexOf(u8, harness_prelude, "__home_s3_file") != null);
    try std.testing.expect(std.mem.indexOf(u8, harness_prelude, "__home_s3_normalize_content_type") != null);

    var runtime = try jsc_bootstrap.Runtime.init(std.testing.allocator, harness_prelude);
    defer runtime.deinit();

    var file_run = try runtime.runFile(std.testing.allocator, prepared.fileSpec());
    defer file_run.deinit(std.testing.allocator);

    if (file_run.result.status() != .passed) {
        std.debug.print("current S3 file type validation failure: {s}\n", .{file_run.result.first_failure_message});
    }
    try std.testing.expectEqual(test_result.TestStatus.passed, file_run.result.status());
    try std.testing.expectEqual(@as(usize, 1), file_run.result.passed);
    try std.testing.expectEqual(@as(usize, 0), file_run.result.todo);
}

