                source_text_module_run.result.failed,
                source_text_module_run.result.unsupported,
                source_text_module_run.result.first_failure_message,
            },
        );
    }
    try std.testing.expectEqual(test_result.TestStatus.passed, source_text_module_run.result.status());
    try std.testing.expectEqual(@as(usize, 1), source_text_module_run.result.passed);
}

test "bootstrap Bun.connect sees websocket upgrade response cookies" {
    if (!build_options.enable_jsc) return error.SkipZigTest;

    const source =
        \\import { expect, test } from "bun:test";
        \\
        \\test("websocket upgrade response cookies", async () => {
        \\  using server = Bun.serve({
        \\    port: 0,
        \\    routes: {
        \\      "/ws": req => {
        \\        req.cookies.set("session", "abc123", { path: "/" });
        \\        req.cookies.set("user", "john", { httpOnly: true });
        \\        if (server.upgrade(req, { headers: { "X-Custom-Header": "test" } })) return undefined;
        \\        return new Response("Upgrade failed", { status: 500 });
        \\      },
        \\    },
        \\    websocket: {
        \\      message(ws, message) {
        \\        ws.close();
        \\      },
        \\    },
        \\  });
        \\  await new Promise((resolve, reject) => {
        \\    Bun.connect({
        \\      hostname: "localhost",
        \\      port: server.port,
        \\      socket: {
        \\        data(socket, data) {
        \\          try {
        \\            const response = new TextDecoder().decode(data);
        \\            expect(response).toContain("HTTP/1.1 101");
        \\            expect(response).toContain("Upgrade: websocket");
        \\            expect(response).toContain("X-Custom-Header: test");
        \\            expect(response).toContain("Set-Cookie:");
        \\            expect(response).toContain("session=abc123");
        \\            expect(response).toContain("user=john");
        \\            socket.end();
        \\            resolve();
        \\          } catch (error) {
        \\            reject(error);
        \\          }
        \\        },
        \\        error(socket, error) {
        \\          reject(error);
        \\        },
        \\      },
        \\    }).then(socket => {
        \\      socket.write(
        \\        "GET /ws HTTP/1.1\r\n" +
        \\          `Host: localhost:${server.port}\r\n` +
        \\          "Upgrade: websocket\r\n" +
        \\          "Connection: Upgrade\r\n" +
        \\          "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n" +
        \\          "Sec-WebSocket-Version: 13\r\n" +
        \\          "\r\n",
        \\      );
        \\    }, reject);
        \\  });
        \\});
