test "bootstrap runner covers current Bun.escapeHTML edge cases" {
    if (!build_options.enable_jsc) return error.SkipZigTest;

    const source =
        \\import { escapeHTML } from "bun";
        \\import { describe, expect, it } from "bun:test";
        \\
        \\describe("escapeHTML current upstream edge cases", () => {
        \\  it("escapes metacharacters adjacent to lone surrogates", () => {
        \\    expect(escapeHTML("\uD800<x")).toBe("\uD800&lt;x");
        \\    expect(escapeHTML("\uD800>x")).toBe("\uD800&gt;x");
        \\    expect(escapeHTML("\uD800<img src=x onerror=alert(1)\uD800>")).toBe("\uD800&lt;img src=x onerror=alert(1)\uD800&gt;");
        \\    expect(escapeHTML(("\uD800<" + "a".repeat(14)).repeat(8))).toBe(("\uD800&lt;" + "a".repeat(14)).repeat(8));
        \\    expect(escapeHTML("\uD800a😊<b")).toBe("\uD800a😊&lt;b");
        \\  });
        \\
        \\  it("escapes every metacharacter and densely packed escapes", () => {
        \\    expect(escapeHTML(`&<>"'`)).toBe("&amp;&lt;&gt;&quot;&#x27;");
        \\    expect(escapeHTML(`<a href="/x?a=1&b=2" title='it\\'s'>`)).toBe("&lt;a href=&quot;/x?a=1&amp;b=2&quot; title=&#x27;it\\&#x27;s&#x27;&gt;");
        \\    expect(escapeHTML("<".repeat(100))).toBe("&lt;".repeat(100));
        \\    expect(escapeHTML("<>".repeat(100))).toBe("&lt;&gt;".repeat(100));
        \\    expect(escapeHTML(`&<>"'`.repeat(50))).toBe("&amp;&lt;&gt;&quot;&#x27;".repeat(50));
        \\  });
        \\
        \\  it("coerces non-string arguments except symbols", () => {
        \\    expect(escapeHTML(123)).toBe("123");
        \\    expect(escapeHTML(true)).toBe("true");
        \\    expect(escapeHTML(false)).toBe("false");
        \\    expect(escapeHTML(null)).toBe("null");
        \\    expect(escapeHTML(undefined)).toBe("undefined");
        \\    expect(escapeHTML({ toString: () => "<b>hi</b>" })).toBe("&lt;b&gt;hi&lt;/b&gt;");
        \\    expect(escapeHTML([1, 2, 3])).toBe("1,2,3");
        \\    expect(() => escapeHTML(Symbol.iterator)).toThrow("Cannot convert a symbol to a string");
        \\  });
        \\
        \\  it("returns the same string when nothing is escaped", () => {
        \\    const latin1 = "a".repeat(64);
        \\    expect(escapeHTML(latin1)).toBe(latin1);
        \\    const utf16 = "café ".repeat(16);
        \\    expect(escapeHTML(utf16)).toBe(utf16);
        \\  });
        \\});
    ;
    var prepared = try prepareCorpusModule(std.testing.allocator, source, "js/bun/util/escapeHTML.test.js");
    defer prepared.deinit(std.testing.allocator);

    try std.testing.expect(prepared.unsupported_reason == null);
    try std.testing.expect(std.mem.indexOf(u8, prepared.source, "const { escapeHTML } = globalThis.__home_import(\"bun\");") != null);

    var runtime = try jsc_bootstrap.Runtime.init(std.testing.allocator, harness_prelude);
    defer runtime.deinit();

    var file_run = try runtime.runFile(std.testing.allocator, prepared.fileSpec());
    defer file_run.deinit(std.testing.allocator);

    if (file_run.result.status() != .passed) {
        std.debug.print("current escapeHTML regression failure: {s}\n", .{file_run.result.first_failure_message});
    }
    try std.testing.expectEqual(test_result.TestStatus.passed, file_run.result.status());
    try std.testing.expectEqual(@as(usize, 4), file_run.result.passed);
    try std.testing.expectEqual(@as(usize, 0), file_run.result.todo);
}

test "bootstrap runner mirrors mixed runtime regression mini-suite" {
    if (!build_options.enable_jsc) return error.SkipZigTest;

    const cases = [_]struct {
        path: []const u8,
        passed: usize,
        alternate_passed: ?usize = null,
        todo: usize = 0,
    }{
        .{ .path = "js/bun/transpiler/transpiler-utf16-loader.test.ts", .passed = 5 },
        .{ .path = "regression/issue/012039.test.ts", .passed = 3 },
        .{ .path = "js/web/html/html-rewriter-doctype.test.ts", .passed = 1 },
        .{ .path = "js/bun/jsonc/jsonc.test.ts", .passed = 14 },
        .{ .path = "js/bun/test/snapshot-tests/snapshots/more-snapshots/different-directory.test.ts", .passed = 1 },
        .{ .path = "js/bun/test/jest-each.test.ts", .passed = 25 },
        .{ .path = "regression/issue/htmlrewriter-additional-bugs.test.ts", .passed = 7 },
        .{ .path = "regression/issue/24191.test.ts", .passed = 2 },
        .{ .path = "regression/issue/28522.test.ts", .passed = 1 },
        .{ .path = "js/bun/resolve/resolve-bad-parent.test.mjs", .passed = 1 },
        .{ .path = "regression/issue/issue-1825-jest-mock-functions.test.ts", .passed = 3 },
        .{ .path = "js/bun/test/expect-toHaveReturnedWith.test.js", .passed = 13 },
        .{ .path = "js/bun/test/mock/mock-module-non-string.test.ts", .passed = 5 },
        .{ .path = "regression/issue/09563/09563.test.ts", .passed = 1 },
        // issue 5228 drives nested `bun test` subprocess fixtures; isolated runs
        // also observe child registrations, while the full suite only counts the
        // four parent tests.
        .{ .path = "regression/issue/5228.test.js", .passed = 14, .alternate_passed = 4 },
        .{ .path = "regression/issue/26377.test.ts", .passed = 3 },
    };

    var threaded = std.Io.Threaded.init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();

    for (cases) |case| {
        var summary = try runFile(io, std.testing.allocator, "packages/runtime/test/bun-corpus", case.path);
        defer summary.deinit(std.testing.allocator);

        const passed_matches = summary.passed == case.passed or (case.alternate_passed != null and summary.passed == case.alternate_passed.?);
        if (summary.failed != 0 or summary.unsupported != 0 or !passed_matches or summary.todo != case.todo) {
            std.debug.print(
                "mixed runtime regression corpus mismatch in {s}: passed={} expected={} alternate_expected={?} failed={} todo={} expected_todo={} unsupported={} message={s}\n",
                .{ case.path, summary.passed, case.passed, case.alternate_passed, summary.failed, summary.todo, case.todo, summary.unsupported, summary.first_failure_message },
            );
        }
        try std.testing.expectEqual(@as(usize, 1), summary.files);
        try std.testing.expect(passed_matches);
        try std.testing.expectEqual(@as(usize, 0), summary.failed);
        try std.testing.expectEqual(case.todo, summary.todo);
        try std.testing.expectEqual(@as(usize, 0), summary.unsupported);
    }
}

