test "bootstrap runner covers current TextEncoder encodeInto astral boundaries" {
    if (!build_options.enable_jsc) return error.SkipZigTest;

    const source =
        \\import { expect, test } from "bun:test";
        \\
        \\test("TextEncoder.encodeInto leaves astral code points unwritten unless the full 4-byte sequence fits", () => {
        \\  const cases = [
        \\    ["\u{1F600}", 3, { read: 0, written: 0 }, [0xaa, 0xaa, 0xaa]],
        \\    ["\u{1F600}", 4, { read: 2, written: 4 }, [0xf0, 0x9f, 0x98, 0x80]],
        \\    ["\u{1F600}", 2, { read: 0, written: 0 }, [0xaa, 0xaa]],
        \\    ["\uD800", 3, { read: 1, written: 3 }, [0xef, 0xbf, 0xbd]],
        \\    ["\uDC00", 3, { read: 1, written: 3 }, [0xef, 0xbf, 0xbd]],
        \\    ["\uD800", 2, { read: 0, written: 0 }, [0xaa, 0xaa]],
        \\    ["a\u{1F600}", 3, { read: 1, written: 1 }, [0x61, 0xaa, 0xaa]],
        \\    ["a\u{1F600}", 4, { read: 1, written: 1 }, [0x61, 0xaa, 0xaa, 0xaa]],
        \\    ["a\u{1F600}", 5, { read: 3, written: 5 }, [0x61, 0xf0, 0x9f, 0x98, 0x80]],
        \\  ];
        \\  for (const [input, size, expectedResult, expectedBytes] of cases) {
        \\    const bytes = new Uint8Array(size).fill(0xaa);
        \\    const result = new TextEncoder().encodeInto(input, bytes);
        \\    expect({ input, size, result, bytes: Array.from(bytes) }).toEqual({ input, size, result: expectedResult, bytes: expectedBytes });
        \\  }
        \\});
    ;
    var prepared = try prepareCorpusModule(std.testing.allocator, source, "js/web/encoding/text-encoder.test.js");
    defer prepared.deinit(std.testing.allocator);

    try std.testing.expect(prepared.unsupported_reason == null);
    try std.testing.expect(std.mem.indexOf(u8, harness_prelude, "TextEncoder.prototype.encodeInto") != null);
    try std.testing.expect(std.mem.indexOf(u8, harness_prelude, "if (written + bytes.length > destination.length) break;") != null);

    var runtime = try jsc_bootstrap.Runtime.init(std.testing.allocator, harness_prelude);
    defer runtime.deinit();

    var file_run = try runtime.runFile(std.testing.allocator, prepared.fileSpec());
    defer file_run.deinit(std.testing.allocator);

    if (file_run.result.status() != .passed) {
        std.debug.print("current TextEncoder encodeInto astral boundary failure: {s}\n", .{file_run.result.first_failure_message});
    }
    try std.testing.expectEqual(test_result.TestStatus.passed, file_run.result.status());
    try std.testing.expectEqual(@as(usize, 1), file_run.result.passed);
    try std.testing.expectEqual(@as(usize, 0), file_run.result.todo);
}

test "bootstrap runner covers current Headers lowercase regressions" {
    if (!build_options.enable_jsc) return error.SkipZigTest;

    const source =
        \\import { expect, test } from "bun:test";
        \\import * as internalForTesting from "bun:internal-for-testing";
        \\
        \\test("Headers iteration lowercases uncommon header names without corrupting token punctuation", () => {
        \\  const tokenPunct = "!#$%&'*+-.^_`|~";
        \\  const names = [...tokenPunct].map((c, i) => `X-Ab${c}Cd${i}`);
        \\  const headers = new Headers();
        \\  const expected = {};
        \\  for (const name of names) {
        \\    headers.append(name, "v");
        \\    expected[name.toLowerCase()] = "v";
        \\  }
        \\  expect(Object.fromEntries(headers)).toEqual(expected);
        \\  expect(Object.fromEntries(headers.entries())).toEqual(expected);
        \\  expect(headers.toJSON()).toEqual(expected);
        \\
        \\  const longName = "X-Custom-Header-" + Buffer.alloc(96, "A").toString() + "^_`|~";
        \\  const single = new Headers();
        \\  single.append(longName, "1");
        \\  expect([...single.keys()]).toEqual([longName.toLowerCase()]);
        \\  expect([...single]).toEqual([[longName.toLowerCase(), "1"]]);
        \\});
        \\
        \\test("lowercaseHeaderNameSIMD matches ASCII-only scalar lowercasing", () => {
        \\  const lower = internalForTesting.lowercaseHeaderNameSIMD;
        \\  expect(typeof lower).toBe("function");
        \\  const scalarLower = s => [...s].map(c => (c >= "A" && c <= "Z" ? c.toLowerCase() : c)).join("");
        \\  const alphabet = "AZaz09@[]^_`{|}~-.Mm";
        \\  for (let len = 0; len <= 160; len++) {
        \\    let input = "";
        \\    for (let i = 0; i < len; i++) input += alphabet[(i * 7 + len) % alphabet.length];
        \\    expect(lower(input)).toBe(scalarLower(input));
        \\  }
        \\  expect(lower("@ABYZ[\\]^_`az{|}~")).toBe("@abyz[\\]^_`az{|}~");
        \\  expect(lower("\u00c0A\u00e0Z\u00ff")).toBe("\u00c0a\u00e0z\u00ff");
        \\  expect(lower("X-Ab\u0100Cd\u0101Ef\uffffGZ")).toBe("x-ab\u0100cd\u0101ef\uffffgz");
        \\});
    ;
    var prepared = try prepareCorpusModule(std.testing.allocator, source, "js/web/fetch/headers.test.ts");
    defer prepared.deinit(std.testing.allocator);

    try std.testing.expect(prepared.unsupported_reason == null);
    try std.testing.expect(std.mem.indexOf(u8, prepared.source, "const internalForTesting = globalThis.__home_import(\"bun:internal-for-testing\");") != null);
    try std.testing.expect(std.mem.indexOf(u8, harness_prelude, "lowercaseHeaderNameSIMD") != null);

    var runtime = try jsc_bootstrap.Runtime.init(std.testing.allocator, harness_prelude);
    defer runtime.deinit();

    var file_run = try runtime.runFile(std.testing.allocator, prepared.fileSpec());
    defer file_run.deinit(std.testing.allocator);

    if (file_run.result.status() != .passed) {
        std.debug.print("current Headers lowercase regression failure: {s}\n", .{file_run.result.first_failure_message});
    }
    try std.testing.expectEqual(test_result.TestStatus.passed, file_run.result.status());
    try std.testing.expectEqual(@as(usize, 2), file_run.result.passed);
    try std.testing.expectEqual(@as(usize, 0), file_run.result.todo);
}

