test "bootstrap runner covers Node url bootstrap smokes" {
    if (!build_options.enable_jsc) return error.SkipZigTest;

    const source =
        \\import { describe, test } from "bun:test";
        \\import assert from "node:assert";
        \\import path from "node:path";
        \\import { URL } from "node:url";
        \\import url from "node:url";
        \\
        \\describe("URL.canParse", () => {
        \\  test("invalid input", () => {
        \\    assert.throws(() => URL.canParse(), { code: "ERR_MISSING_ARGS", name: "TypeError" });
        \\  });
        \\
        \\  test("repeatedly called produces same result", () => {
        \\    for (let i = 0; i < 10; i++) {
        \\      assert(URL.canParse("https://www.example.com/path/?query=param#hash"));
        \\    }
        \\  });
        \\});
        \\
        \\describe("url.format", () => {
        \\  test("invalid input", () => {
        \\    assert.throws(() => url.format(null), { code: "ERR_INVALID_ARG_TYPE", name: "TypeError" });
        \\  });
        \\
        \\  test("empty", () => {
        \\    assert.strictEqual(url.format(""), "");
        \\    assert.strictEqual(url.format({}), "");
        \\  });
        \\
        \\  test("format encodes every hash character in the search component", () => {
        \\    const formatted = url.format({
        \\      protocol: "http:",
        \\      hostname: "example.com",
        \\      pathname: "/",
        \\      search: "?foo=bar#1#2#3&abc=#4##5",
        \\    });
        \\    assert.strictEqual(formatted, "http://example.com/?foo=bar%231%232%233&abc=%234%23%235");
        \\
        \\    const reparsed = url.parse(formatted);
        \\    assert.strictEqual(reparsed.search, "?foo=bar%231%232%233&abc=%234%23%235");
        \\    assert.strictEqual(reparsed.hash, null);
        \\    assert.strictEqual(url.format({ protocol: "http:", hostname: "example.com", pathname: "/", search: "?a=#1" }), "http://example.com/?a=%231");
        \\  });
        \\});
        \\
        \\describe("path.format", () => {
        \\  test("formats dot-less ext for long paths", () => {
        \\    const dir = "/" + "d".repeat(70000);
        \\    const name = "n".repeat(70000);
        \\    const ext = "txt";
        \\    assert.strictEqual(path.posix.format({ dir, name, ext }), dir + "/" + name + "." + ext);
        \\    assert.strictEqual(path.win32.format({ dir, name, ext }), dir + "\\" + name + "." + ext);
        \\    assert.strictEqual(path.posix.format({ dir: "/tmp", name: "file", ext: "txt" }), "/tmp/file.txt");
        \\  });
        \\});
    ;
    var prepared = try prepareCorpusModule(std.testing.allocator, source, "js/node/url/url-bootstrap-smoke.test.js");
    defer prepared.deinit(std.testing.allocator);

    var runtime = try jsc_bootstrap.Runtime.init(std.testing.allocator, harness_prelude);
    defer runtime.deinit();

    var file_run = try runtime.runFile(std.testing.allocator, prepared.fileSpec());
    defer file_run.deinit(std.testing.allocator);

    try std.testing.expectEqual(test_result.TestStatus.passed, file_run.result.status());
    try std.testing.expectEqual(@as(usize, 6), file_run.result.passed);
    try std.testing.expectEqual(@as(usize, 0), file_run.result.todo);
}

