        \\  expect(await proc.exited).toBe(0);
        \\  out = await proc.stdout.text();
        \\  expect(out).toContain("Blocked 2 postinstalls");
        \\  expect(await exists(join(packageDir, "node_modules/uses-what-bin/what-bin.txt"))).toBeFalse();
