        \\    new Map([["outer", new Map([["inner1", 1]])]]),
        \\  );
        \\});
        \\
        \\test("partialDeepStrictEqual with Map - circular reference", () => {
        \\  const actualMap = new Map<string, unknown>();
        \\  actualMap.set("self", actualMap);
