        \\import { createCipheriv, createDecipheriv, createPrivateKey, createPublicKey, createSecretKey, generateKey, generateKeyPair, generateKeyPairSync, generateKeySync, KeyObject, randomBytes } from "node:crypto";
        \\
        \\const rsaPrivate = "-----BEGIN RSA PRIVATE KEY-----\nMIIBOgIBAAJBALfcWIiCJ7HAt78/wNnHkeyoWWZQ7v+W8nud5wlU3Cp1ndrHmOlA\nHXHq7F+p46/Nw3eTlXkFb/AW+nkSNZMAZhsCAwEAAQJBALf9WqcqrCOaTZhv4gVE\nCsw+fbq4+nbzFh189YxlpelAWETON4oywvj/Kz53vRc9eiKhxVuWoDXEIEcqa48C\nCAE=\n-----END RSA PRIVATE KEY-----\n";
        \\const edPrivate = "-----BEGIN PRIVATE KEY-----\nMC4CAQAwBQYDK2VwBCIEIMFSujN0jIUIdzSvuxka0lfgVVkMdRTuaVvIYUHrvzXQ\n-----END PRIVATE KEY-----\n";
        \\const ecPrivate = "-----BEGIN PRIVATE KEY-----\nMIGHAgEAMBMGByqGSM49AgEGCCqGSM49AwEHBG0wawIBAQQgDxBsPQPIgMuMyQbx\nzbb9toew6Ev6e9O6ZhpxLNgmAEqhRANCAARfSYxhH+6V5lIg+M3O0iQBLf+53kuE\n2luIgWnp81/Ya1Gybj8tl4tJVu1GEwcTyt8hoA7vRACmCHnI5B1+bNpS\n-----END PRIVATE KEY-----\n";
        \\
        \\test("secret KeyObject branding and cipher bytes", () => {
        \\  expect(() => new KeyObject("secret")).toThrow();
        \\  const raw = randomBytes(32);
        \\  const key = createSecretKey(raw);
        \\  expect(key.type).toBe("secret");
        \\  expect(key.toString()).toBe("[object KeyObject]");
        \\  expect(key.symmetricKeySize).toBe(32);
        \\  expect(key.export()).toEqual(raw);
        \\  expect(key.export({ format: "jwk" })).toEqual({ kty: "oct", k: raw.toString("base64url") });
        \\  const cipher = createCipheriv("aes-256-ecb", key, null);
        \\  const encrypted = Buffer.concat([cipher.update(Buffer.from("hello")), cipher.final()]);
        \\  const decipher = createDecipheriv("aes-256-ecb", key, null);
        \\  expect(Buffer.concat([decipher.update(encrypted), decipher.final()])).toEqual(Buffer.from("hello"));
        \\});
        \\
        \\test("asymmetric KeyObject fixtures expose type, jwk, and details", () => {
        \\  const rsa = createPrivateKey(rsaPrivate);
        \\  expect(rsa.toString()).toBe("[object KeyObject]");
        \\  expect(rsa.asymmetricKeyType).toBe("rsa");
        \\  expect(createPublicKey(rsa).export({ format: "jwk" }).e).toBe("AQAB");
        \\  const ed = createPrivateKey(edPrivate);
        \\  expect(ed.asymmetricKeyType).toBe("ed25519");
        \\  expect(ed.export({ format: "jwk" }).crv).toBe("Ed25519");
        \\  const ec = createPrivateKey(ecPrivate);
        \\  expect(ec.asymmetricKeyType).toBe("ec");
        \\  expect(ec.asymmetricKeyDetails?.namedCurve).toBe("prime256v1");
        \\  expect(ec.export({ format: "jwk" }).kty).toBe("EC");
        \\});
        \\
        \\test("encrypted private key passphrases validate", () => {
        \\  const encrypted = "-----BEGIN RSA PRIVATE KEY-----\nProc-Type: 4,ENCRYPTED\nDEK-Info: AES-256-CBC,HOME\n-----END RSA PRIVATE KEY-----\n";
        \\  expect(() => createPrivateKey(encrypted)).toThrow();
        \\  expect(() => createPrivateKey({ key: encrypted, passphrase: "wrong" })).toThrow();
        \\  expect(createPrivateKey({ key: encrypted, passphrase: "password" }).type).toBe("private");
        \\});
        \\
        \\test("rsa fixture details", () => {
        \\  const rsa2048 = "-----BEGIN PUBLIC KEY-----\nMIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8AMIIBCgKCAQEArk4OqxBqU5/k0FoUDU7C\npZpjz6YJEXUpyqeJmFRVZPMUv/Rc7U4seLY+Qp6k26T/wlQ2WJWuyY+VJcbQNWLv\njJWks5HWknwDuVs6sjuTM8CfHWn1960JkK5Ec2TjRhCQ1KJy+uc3GJLtWb4rWVgT\nbbaaC5fiR1/GeuJ8JH1Q50lB3mDsNGIk1U5jhNaYY82hYvlbErf6Ft5njHK0BOM5\nOTvQ6BBv7c363WNG7tYlNw1J40dup9OQPo5JmXN/h+sRbdgG8iUxrkRibuGv7loh\n52QQgq2snznuRMdKidRfUZjCDGgw3meAHfpGhGaYsCFW9KFkAW4Seetcc3CTY5WN\nroCj2gnXHXIL6VM02jFqjQIDAQAB\n-----END PUBLIC KEY-----\n";
        \\  expect(createPublicKey(rsa2048).asymmetricKeyDetails).toEqual({ modulusLength: 2048, publicExponent: 65537n });
        \\});
