        \\  expect(ec.publicKey.asymmetricKeyType).toBe("ec");
        \\  expect(ec.publicKey.asymmetricKeyDetails).toEqual({ namedCurve: "prime256v1" });
        \\  const ecJwk = await new Promise((resolve, reject) => generateKeyPair("ec", { namedCurve: "P-384", publicKeyEncoding: { format: "jwk" }, privateKeyEncoding: { format: "jwk" } }, (err, publicKey, privateKey) => err ? reject(err) : resolve({ publicKey, privateKey })));
        \\  expect(ecJwk.publicKey.kty).toBe("EC");
        \\  expect(ecJwk.publicKey.crv).toBe("P-384");
        \\  expect(ecJwk.privateKey.d).toBeDefined();
        \\  const rsaJwk = await new Promise((resolve, reject) => generateKeyPair("rsa", { modulusLength: 512, publicKeyEncoding: { format: "jwk" }, privateKeyEncoding: { format: "jwk" } }, (err, publicKey, privateKey) => err ? reject(err) : resolve({ publicKey, privateKey })));
        \\  expect(rsaJwk.publicKey.kty).toBe("RSA");
        \\  expect(rsaJwk.publicKey.n).toBe(rsaJwk.privateKey.n);
        \\  expect(rsaJwk.privateKey.qi).toBeDefined();
        \\  const okpJwk = await new Promise((resolve, reject) => generateKeyPair("x25519", { publicKeyEncoding: { format: "jwk" }, privateKeyEncoding: { format: "jwk" } }, (err, publicKey, privateKey) => err ? reject(err) : resolve({ publicKey, privateKey })));
        \\  expect(okpJwk.publicKey.kty).toBe("OKP");
        \\  expect(okpJwk.publicKey.crv).toBe("X25519");
        \\  expect(okpJwk.privateKey.d).toBeDefined();
        \\});
