        \\import crypto from "node:crypto";
        \\
        \\test("node crypto corpus smoke", async () => {
        \\  expect(() => crypto.createHash("rsa-md5")).toThrow(Error("Digest method not supported"));
        \\  const hash = crypto.createHash("rsa-sha1").update("Hello World");
        \\  const copy = hash.copy();
        \\  expect(hash.digest("hex")).toBe("0a4d55a8d778e5022fab701977c5d840bbc486d0");
        \\  expect(copy.digest("hex")).toBe("0a4d55a8d778e5022fab701977c5d840bbc486d0");
        \\  expect(() => hash.copy()).toThrow(Error("Digest already called"));
        \\  const streamHash = crypto.createHash("sha256");
        \\  streamHash.write("some data to hash");
        \\  streamHash.end();
        \\  expect(streamHash.read().toString("hex")).toBe("6a2da20943931e9834fc12cfe5bb47bbd9ae43489a30726962b576f4e3993e50");
        \\  expect(crypto.createHmac("sha256", "key").update("message").digest("base64")).toBe("bp7ym3X//Ft6uuUn1Y/a2y/kLnIZARl2kXNDBl9Y7Uo=");
        \\  const bytes = new Uint8Array(8);
        \\  expect(crypto.getRandomValues(bytes)).toBe(bytes);
        \\  expect(await crypto.subtle.digest("SHA-256", bytes)).toBeInstanceOf(ArrayBuffer);
        \\  expect(crypto.generatePrimeSync(64)).toBeInstanceOf(ArrayBuffer);
        \\  const pair = crypto.generateKeyPairSync("x25519", { publicKeyEncoding: { type: "spki", format: "der" }, privateKeyEncoding: { type: "pkcs8", format: "der" } });
        \\  const secret = crypto.diffieHellman({ privateKey: crypto.createPrivateKey({ key: pair.privateKey, format: "der", type: "pkcs8" }), publicKey: crypto.createPublicKey({ key: pair.publicKey, format: "der", type: "spki" }) });
        \\  expect(secret.length).toBe(32);
        \\});
    ;
