test "bootstrap runner models bun install invalid network concurrency" {
    if (!build_options.enable_jsc) return error.SkipZigTest;

    const source =
        \\import { spawn } from "bun";
        \\import { expect, test } from "bun:test";
        \\import { writeFile } from "fs/promises";
        \\import { bunEnv as env, bunExe } from "harness";
        \\import { join } from "path";
        \\import { createTestContext, destroyTestContext, dummyRegistryForContext, setContextHandler } from "./dummy.registry.js";
        \\
        \\for (const input of ["abcdef", "65537", "-1"]) {
        \\  test(`bun install --network-concurrency=${input} fails`, async () => {
        \\    const ctx = await createTestContext({ linker: "hoisted" });
        \\    try {
        \\      const urls = [];
        \\      setContextHandler(ctx, dummyRegistryForContext(ctx, urls));
        \\      await writeFile(join(ctx.package_dir, "package.json"), JSON.stringify({
        \\        name: "foo",
        \\        version: "0.0.1",
        \\        dependencies: {
        \\          bar: "^1",
        \\        },
        \\      }));
        \\      const { stderr, exited } = spawn({
        \\        cmd: [bunExe(), "install", "--network-concurrency", input],
        \\        cwd: ctx.package_dir,
        \\        stdout: "ignore",
        \\        stdin: "ignore",
        \\        stderr: "pipe",
        \\        env,
        \\      });
        \\      expect(await stderr.text()).toContain("Expected --network-concurrency to be a number between 0 and 65535");
        \\      expect(await exited).toBe(1);
        \\      expect(urls).toEqual([]);
        \\      expect(ctx.requested).toBe(0);
        \\    } finally {
        \\      destroyTestContext(ctx);
        \\    }
        \\  });
        \\}
        \\
        \\test("bun install --network-concurrency=5 respects request budget", async () => {
        \\  const ctx = await createTestContext({ linker: "hoisted" });
        \\  try {
        \\    let active = 0;
        \\    let maxActive = 0;
        \\    let total = 0;
        \\    setContextHandler(ctx, async () => {
        \\      active++;
        \\      total++;
        \\      await Bun.sleep(1);
        \\      maxActive = Math.max(maxActive, active);
        \\      active--;
        \\      return new Response("404", { status: 404 });
        \\    });
        \\    const dependencies = {};
        \\    for (let i = 1; i <= 10; i++) dependencies["bar" + i] = "^1";
        \\    await writeFile(join(ctx.package_dir, "package.json"), JSON.stringify({ name: "foo", version: "0.0.1", dependencies }));
        \\    const { stdout, stderr, exited } = spawn({
        \\      cmd: [bunExe(), "install", "--network-concurrency", "5"],
        \\      cwd: ctx.package_dir,
        \\      stdout: "pipe",
        \\      stdin: "ignore",
        \\      stderr: "pipe",
        \\      env,
        \\    });
        \\    expect(await stderr.text()).toContain("failed to resolve");
        \\    expect(await stdout.text()).toEqual(expect.stringContaining("bun install v1."));
        \\    expect(await exited).toBe(1);
        \\    expect(total).toBe(10);
        \\    expect(maxActive).toBeLessThanOrEqual(5);
        \\  } finally {
        \\    destroyTestContext(ctx);
        \\  }
        \\});
    ;

