        \\
        \\expect.extend({ toBeValidBin, toHaveBins });
        \\
        \\async function runInstall(expectSavedLockfile, mooTarball) {
        \\  const { stdout, stderr, exited } = spawn({
        \\    cmd: [bunExe(), "install"],
        \\    cwd: package_dir,
        \\    stdout: "pipe",
        \\    stdin: "pipe",
        \\    stderr: "pipe",
        \\    env,
        \\  });
        \\  const err = await stderr.text();
        \\  if (expectSavedLockfile) {
        \\    expect(err).toContain("Saved lockfile");
        \\  } else {
        \\    expect(err).not.toContain("Saved lockfile");
        \\  }
        \\  const out = await stdout.text();
        \\  const display = mooTarball.replace(/\\/g, "/");
        \\  expect(out.replace(/\s*\[[0-9\.]+m?s\]\s*$/, "").split(/\r?\n/)).toEqual([
        \\    expect.stringContaining("bun install v1."),
        \\    "",
        \\    `+ @barn/moo@${display}`,
        \\    "",
        \\    "3 packages installed",
        \\  ]);
        \\  expect(await exited).toBe(0);
        \\}
        \\
        \\async function expectGraph() {
        \\  expect(await readdirSorted(join(package_dir, "node_modules"))).toEqual([".bin", ".cache", "@barn", "bar", "baz"]);
        \\  expect(await readdirSorted(join(package_dir, "node_modules", ".bin"))).toHaveBins(["baz-run"]);
        \\  expect(join(package_dir, "node_modules", ".bin", "baz-run")).toBeValidBin(join("..", "baz", "index.js"));
        \\  expect(await readdirSorted(join(package_dir, "node_modules", "@barn"))).toEqual(["moo"]);
        \\  expect(await readdirSorted(join(package_dir, "node_modules", "@barn", "moo"))).toEqual(["package.json"]);
        \\  expect(await file(join(package_dir, "node_modules", "@barn", "moo", "package.json")).json()).toEqual({
        \\    name: "@barn/moo",
        \\    version: "0.1.0",
        \\    dependencies: {
        \\      bar: "0.0.2",
        \\      baz: "latest",
        \\    },
        \\  });
        \\  expect(await file(join(package_dir, "node_modules", "bar", "package.json")).json()).toEqual({
        \\    name: "bar",
        \\    version: "0.0.2",
        \\  });
        \\  expect(await file(join(package_dir, "node_modules", "baz", "package.json")).json()).toEqual({
        \\    name: "baz",
        \\    version: "0.0.3",
        \\    bin: {
        \\      "baz-run": "index.js",
        \\    },
        \\  });
        \\  await access(join(package_dir, "bun.lockb"));
        \\}
        \\
        \\async function expectExistingLockfileInstall(mooTarball, firstUrls, secondUrls) {
        \\  await dummyBeforeEach({ linker: "hoisted" });
        \\  const urls = [];
        \\  setHandler(dummyRegistry(urls, {
        \\    "0.0.2": {},
        \\    "0.0.3": {
        \\      bin: {
        \\        "baz-run": "index.js",
        \\      },
        \\    },
        \\  }));
        \\  if (!/^https?:\/\//.test(mooTarball)) {
        \\    await writeFile(mooTarball, "home tarball fixture");
        \\  }
        \\  await writeFile(join(package_dir, "package.json"), JSON.stringify({
        \\    name: "foo",
        \\    version: "0.0.1",
        \\    dependencies: {
        \\      "@barn/moo": mooTarball,
        \\    },
        \\  }));
        \\  await runInstall(true, mooTarball);
        \\  expect(urls.sort()).toEqual(firstUrls);
        \\  expect(requested).toBe(firstUrls.length);
        \\  await expectGraph();
        \\
        \\  await rm(join(package_dir, "node_modules"), { force: true, recursive: true });
        \\  urls.length = 0;
        \\  await runInstall(false, mooTarball);
        \\  expect(urls.sort()).toEqual(secondUrls);
        \\  expect(requested).toBe(firstUrls.length + secondUrls.length);
        \\  await expectGraph();
        \\}
        \\
        \\test("should handle tarball URL with existing lockfile", async () => {
        \\  await expectExistingLockfileInstall(`${root_url}/moo-0.1.0.tgz`, [
