        \\  ], [
        \\    `${root_url}/bar-0.0.2.tgz`,
        \\    `${root_url}/baz-0.0.3.tgz`,
        \\    `${root_url}/moo-0.1.0.tgz`,
        \\  ]);
        \\});
        \\
        \\test("should handle tarball path with existing lockfile", async () => {
        \\  await expectExistingLockfileInstall(join(package_dir, "moo-0.1.0.tgz"), [
        \\    `${root_url}/bar`,
        \\    `${root_url}/bar-0.0.2.tgz`,
        \\    `${root_url}/baz`,
        \\    `${root_url}/baz-0.0.3.tgz`,
        \\  ], [
