test "bootstrap runner models bun link registry lifecycle" {
    if (!build_options.enable_jsc) return error.SkipZigTest;

    const source =
        \\import { file, spawn } from "bun";
        \\import { expect, test } from "bun:test";
        \\import { bunEnv as env, bunExe, runBunInstall, tempDirWithFiles } from "harness";
        \\import { join } from "path";
        \\
        \\test("registers, installs, and unregisters linked packages", async () => {
        \\  const provider = tempDirWithFiles("bun-link-provider", {
        \\    "package.json": JSON.stringify({ name: "linked-pkg", version: "1.2.3", bin: { linked: "linked.py" } }),
        \\    "linked.py": "#!/usr/bin/env python\\r\\nprint('linked')",
        \\  });
        \\  const consumer = tempDirWithFiles("bun-link-consumer", {
        \\    "package.json": JSON.stringify({ name: "consumer", dependencies: { "linked-pkg": "link:linked-pkg" } }),
        \\  });
        \\  let child = spawn({ cmd: [bunExe(), "link"], cwd: provider, stdout: "pipe", stderr: "pipe", env });
        \\  expect(await child.stdout.text()).toContain('Success! Registered "linked-pkg"');
        \\  expect(await child.stderr.text()).toBe("");
        \\  expect(await child.exited).toBe(0);
        \\  const installed = await runBunInstall(env, consumer);
        \\  expect(installed.out).toContain("+ linked-pkg@link:linked-pkg");
        \\  expect(installed.err).toContain("Saved lockfile");
        \\  expect(await installed.exited).toBe(0);
        \\  expect(await file(join(consumer, "node_modules", "linked-pkg", "package.json")).json()).toEqual({
        \\    name: "linked-pkg",
        \\    version: "1.2.3",
        \\    bin: { linked: "linked.py" },
        \\  });
        \\  expect(await file(join(consumer, "node_modules", "linked-pkg", "linked.py")).text()).toContain("print('linked')");
        \\  child = spawn({ cmd: [bunExe(), "unlink"], cwd: provider, stdout: "pipe", stderr: "pipe", env });
        \\  expect(await child.stdout.text()).toContain('success: unlinked package "linked-pkg"');
        \\  expect(await child.exited).toBe(0);
        \\  child = spawn({ cmd: [bunExe(), "install"], cwd: consumer, stdout: "pipe", stderr: "pipe", env });
        \\  expect(await child.stderr.text()).toContain("failed linking dependency/workspace");
        \\  expect(await child.exited).toBe(1);
        \\});
    ;

